export const getRangeError = (translateFn, currentVal, defMin, defMax) => {
    if (defMin !== undefined && defMax !== undefined && currentVal !== null && (currentVal < defMin || currentVal > defMax)) {
        return translateFn("Must be in range {min} - {max}").replace("{min}", defMin.toString()).replace("{max}", defMax.toString());
    }
    if (defMin !== undefined && currentVal !== null && currentVal < defMin) {
        return translateFn("Must be more than {value}").replace("{value}", defMin.toString());
    }
    if (defMax !== undefined && currentVal !== null && currentVal > defMax) {
        return translateFn("Must be less than {value}").replace("{value}", defMax.toString());
    }
    return undefined;
};
export const getErrorString = (currentId, currentVal, translateFn, errorType, defMin, defMax) => {
    if (errorType === "bound") {
        return currentVal === null ? translateFn(currentId === "min" ? "The min value must be set" : "The max value must be set") : undefined;
    }
    if (errorType === "range") {
        return getRangeError(translateFn, currentVal, defMin, defMax);
    }
    if (errorType === "value") {
        return currentId === "min" ? translateFn("Must be less than the max") : translateFn("Must be more than the min");
    }
    return undefined;
};
// eslint-disable-next-line complexity
export const checkErrorType = (minVal, maxVal, isFullBounded = false, allowEqualMinMax = false, defMin, defMax) => {
    if (isFullBounded && (minVal === null || maxVal === null)) {
        return "bound";
    }
    if (minVal !== null && maxVal !== null && !(allowEqualMinMax ? maxVal >= minVal : maxVal > minVal)) {
        return "value";
    }
    if (defMin !== undefined && defMax !== undefined && minVal !== null && (minVal < defMin || minVal > defMax)
        || defMin !== undefined && minVal !== null && minVal < defMin
        || defMax !== undefined && minVal !== null && minVal > defMax) {
        return "range";
    }
    if (defMin !== undefined && defMax !== undefined && maxVal !== null && (maxVal < defMin || maxVal > defMax)
        || defMin !== undefined && maxVal !== null && maxVal < defMin
        || defMax !== undefined && maxVal !== null && maxVal > defMax) {
        return "range";
    }
    return undefined;
};
